text:
{
  "axioms": [
    "灯台の灯りは嵐の夜に消してはいけない。消えれば入り江を目指す船は岩礁に乗り上げる。",
    "死者は戻らない。死んだ人物について語れるのは、本人が遺した物と言葉だけである。"
  ],
  "rules": [
    {
      "id": "rule-1",
      "statement": "灯台守は嵐の夜、日没から夜明けまで灯りを絶やしてはいけない",
      "cost": "灯りを守る者は夜通し灯室を離れられず、眠れない",
      "constraint": "油の補給と芯の手入れを夜のあいだに繰り返す必要があり、一人では何日も持ちこたえられない",
      "exception": "霧で海が凪いだ夜だけ、仮灯に切り替えて短く休める",
      "exception_condition": "嵐ではなく、港町側から仮灯の合図があった場合に限る"
    },
    {
      "id": "rule-2",
      "statement": "灯台の鍵は灯台守の家の者だけが持ち、貸すときは相手と理由を明らかにする",
      "cost": "鍵を貸した者は、鍵が戻るまで灯室の扉を閉めて守れない",
      "constraint": "鍵は限られており、貸した鍵が戻らなければ灯りの管理そのものが危うくなる",
      "exception": "遭難の恐れがある緊急時だけ、記録より先に貸せる",
      "exception_condition": "入り江に船が避難し、人命の危険がある場合に限る"
    },
    {
      "id": "rule-3",
      "statement": "灯台と港町のあいだは、山道でも舟でも二日かかる",
      "cost": "往復すれば四日かかり、そのあいだ灯台の守りは残る者に託すしかない",
      "constraint": "嵐の日は舟が出ず、山道も荒れて渡れない",
      "exception": "",
      "exception_condition": ""
    }
  ],
  "institutions": [
    {"name": "灯台守の家", "role": "灯台の点灯と鍵の管理を受け継ぐ"},
    {"name": "港町の船問屋", "role": "入り江に出入りする船の取り次ぎと、仮灯の合図を担う"}
  ],
  "geography": ["灯台", "港町"],
  "disclosure": [
    {"info": "灯りを消してはいけないという掟", "chapter": "ch01"},
    {"info": "鍵に兄の刻印があり、久乃に託されていたこと", "chapter": "ch02"},
    {"info": "源蔵が三年前の夜について黙っていた理由", "chapter": "ch03"}
  ],
  "notes": ""
}
